class Solution {
public:
    int minimumTime(vector<int>& nums1, vector<int>& nums2, int x) {
        int n = nums1.size();
        vector<int> idx(n); iota(idx.begin(), idx.end(), 0);
        sort(idx.begin(), idx.end(), [&](int a, int b){ return nums2[a] > nums2[b]; });
        long long s1 = accumulate(nums1.begin(), nums1.end(), 0LL);
        long long s2 = accumulate(nums2.begin(), nums2.end(), 0LL);
        vector<long long> dp(n + 1, LLONG_MIN); dp[0] = 0;
        for (int m = 1; m <= n; ++m) {
            int i = idx[m-1];
            for (int j = m; j >= 1; --j)
                dp[j] = max(dp[j], dp[j-1] + nums1[i] + (long long)nums2[i] * j);
            for (int t = 1; t <= m; ++t)
                if (s1 + s2 * t - dp[t] <= x) return t;
        }
        return -1;
    }
};

