class Solution {
    public int minimumTime(List<Integer> nums1, List<Integer> nums2, int x) {
        int n = nums1.size();
        Integer[] idx = new Integer[n];
        for (int i = 0; i < n; i++) idx[i] = i;
        Arrays.sort(idx, (a, b) -> nums2.get(b) - nums2.get(a));
        long s1 = 0, s2 = 0;
        for (int i = 0; i < n; i++) { s1 += nums1.get(i); s2 += nums2.get(i); }
        long[] dp = new long[n + 1];
        Arrays.fill(dp, Long.MIN_VALUE); dp[0] = 0;
        for (int m = 1; m <= n; m++) {
            int i = idx[m - 1];
            for (int j = m; j >= 1; j--)
                dp[j] = Math.max(dp[j], dp[j-1] + nums1.get(i) + (long) nums2.get(i) * j);
            for (int t = 1; t <= m; t++)
                if (s1 + s2 * t - dp[t] <= x) return t;
        }
        return -1;
    }
}

