var minimumTime = function(nums1, nums2, x) {
    const n = nums1.length;
    const idx = [...Array(n).keys()].sort((a, b) => nums2[b] - nums2[a]);
    let s1 = 0, s2 = 0;
    for (let i = 0; i < n; i++) { s1 += nums1[i]; s2 += nums2[i]; }
    const dp = Array(n + 1).fill(-Infinity); dp[0] = 0;
    for (let m = 1; m <= n; m++) {
        const i = idx[m - 1];
        for (let j = m; j >= 1; j--)
            dp[j] = Math.max(dp[j], dp[j-1] + nums1[i] + nums2[i] * j);
        for (let t = 1; t <= m; t++)
            if (s1 + s2 * t - dp[t] <= x) return t;
    }
    return -1;
};
